// ─── File: PartitionDemo.java ───
// Runnable demo showing parallelism, scalability, and ordering via partitions.
package com.bank.partition.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class PartitionDemo {
    private static final Logger log = Logger.getLogger(PartitionDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PartitionedTopic topic = new PartitionedTopic("transactions", 3);

        // Burst of events for three accounts (keyed by account id)
        topic.produce("SAV2001", new TxnEvent("T1", "SAV2001", new BigDecimal("50000"), "DEBIT"));
        topic.produce("CUR3001", new TxnEvent("T2", "CUR3001", new BigDecimal("8000"), "CREDIT"));
        topic.produce("SAV2001", new TxnEvent("T3", "SAV2001", new BigDecimal("0"), "BALANCE_CHECK"));
        topic.produce("SAV9999", new TxnEvent("T4", "SAV9999", new BigDecimal("1500"), "DEBIT"));
        topic.produce("SAV2001", new TxnEvent("T5", "SAV2001", new BigDecimal("2000"), "DEBIT"));

        // 3 partitions => up to 3 workers in parallel, one partition each
        ConsumerGroup group = new ConsumerGroup("txn-processors", topic, 3);
        group.processAll();
    }
}

// ─── Would be in TxnEvent.java ───
class TxnEvent {
    private final String id, accountId, type;
    private final BigDecimal amount;
    TxnEvent(String id, String accountId, BigDecimal amount, String type) {
            this.id = id;
            this.accountId = accountId
            this.amount = amount
            this.type = type;
    }
    String getAccountId() { return accountId; }
    @Override public String toString() { return id + " " + accountId + " " + type + " " + amount; }
}

// ─── Would be in PartitionedTopic.java ───
class PartitionedTopic {
    private static final Logger log = Logger.getLogger(PartitionedTopic.class.getName());
    private final String name;
    private final List<List<TxnEvent>> partitions = new ArrayList<>();
    PartitionedTopic(String name, int count) {
        this.name = name;
        for (int i = 0; i < count; i++) partitions.add(new ArrayList<>());
    }
    int partitionCount() { return partitions.size(); }
    int partitionFor(String key) { return Math.floorMod(key.hashCode(), partitions.size()); }
    void produce(String key, TxnEvent e) {
        int p = partitionFor(key);
        partitions.get(p).add(e);
        log.info(() -> "PRODUCE " + name + " key=" + key + " -> partition " + p + " [" + e + "]");
    }
    List<TxnEvent> partition(int id) { return partitions.get(id); }
}

// ─── Would be in ConsumerGroup.java ───
class ConsumerGroup {
    private static final Logger log = Logger.getLogger(ConsumerGroup.class.getName());
    private final String groupId;
    private final PartitionedTopic topic;
    private final int consumerCount;
    ConsumerGroup(String groupId, PartitionedTopic topic, int consumerCount) {
            this.groupId = groupId;
            this.topic = topic
            this.consumerCount = consumerCount;
    }
    // Assign one partition per consumer; consumers process in parallel threads
    void processAll() {
        int partitions = topic.partitionCount();
        log.info(() -> "Group " + groupId + ": " + consumerCount
                + " consumers for " + partitions + " partitions (one each)");
        List<Thread> threads = new ArrayList<>();
        for (int p = 0; p < partitions; p++) {
            Worker w = new Worker(groupId, p, topic.partition(p));
            Thread t = new Thread(w::run, "consumer-" + p);
            threads.add(t); t.start();
        }
        for (Thread t : threads) { try { t.join(); } catch (InterruptedException ignored) {} }
    }
}

// ─── Would be in Worker.java ───
class Worker {
    private static final Logger log = Logger.getLogger(Worker.class.getName());
    private final String groupId;
    private final int partitionId;
    private final List<TxnEvent> events;
    Worker(String groupId, int partitionId, List<TxnEvent> events) {
            this.groupId = groupId;
            this.partitionId = partitionId
            this.events = events;
    }
    void run() {
        // Ordering guaranteed WITHIN this partition
        for (TxnEvent e : events) {
            log.info(() -> "[" + groupId + "] consumer=" + partitionId
                    + " processed (in order) " + e);
        }
    }
}

